@ExtendWith(MockitoExtension.class)
 class FrontendControllerTest {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void setUp(){
    FrontendController.totalCost = new Money("USD", 0L, 0);
    FrontendController.totalQuantity = 0;
    mockMvc = MockMvcBuilders.standaloneSetup(controller).setViewResolvers(NO_OP_VIEW_RESOLVER).build();
    Money price = new Money("USD", 25L, 900000000);
    sampleProduct = new Product("PROD001", "Test Widget", "A great widget", "/images/widget.png", price, List.of("widgets"));
    sampleShippingQuote = new GetQuoteResponse(new Money("USD", 8L, 990000000));
    emptyRecommendations = new ListRecommendationsResponse(Collections.emptyList());
    Ad sampleAd = new Ad("/product/PROD001", "Special offer on Test Widget!");
    sampleAdResponse = new AdResponse();
    sampleAdResponse.setAds(List.of(sampleAd));
}
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void checkout_resetsTotalQuantityToZero() throws Exception{
    FrontendController.totalQuantity = 3;
    when(checkoutService.placeOrder(any())).thenReturn(new PlaceOrderResponse(buildSampleOrderResult()));
    when(recommendationService.listRecommendations(any())).thenReturn(emptyRecommendations);
    mockMvc.perform(buildCheckoutPost());
    assert FrontendController.totalQuantity == 0 : "Expected totalQuantity=0 after /cart/checkout";
}
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private OrderResult buildSampleOrderResult(){
        OrderResult r = new OrderResult();
        r.setOrderId("ORDER-TEST-001");
        r.setShippingTrackingId("TRACK-ABC-123");
        r.setShippingCost(new Money("USD", 8L, 990000000));
        r.setShippingAddress(new Address("1600 Amphitheatre Pkwy", "Mountain View", "CA", "United States", 94043));
        r.setItems(new ArrayList<>());
        return r;
    }
private org.springframework.test.web.servlet.RequestBuilder buildCheckoutPost(){
        return post("/cart/checkout").param("userId", "1").param("userCurrency", "USD").param("email", "buyer@example.com").param("address.streetAddress", "1600 Amphitheatre Pkwy").param("address.zipCode", "94043").param("address.city", "Mountain View").param("address.state", "CA").param("address.country", "United States").param("creditCard.creditCardNumber", "4432-8015-6152-0454").param("creditCard.creditCardCvv", "123").param("creditCard.creditCardExpirationYear", "2026").param("creditCard.creditCardExpirationMonth", "12");
    }
/**************TEST HELPER METHOD END*************/


